import astroid
from astroid import nodes

# Parse the code with the issue
code = """
from typing import TypeVar, cast

T = TypeVar("T")

def ident(var: T) -> T:
    return cast(T, var)

# First call works correctly
result1 = ident(2)  # Should infer as int
# Second call fails to infer correctly
result2 = ident("Hello")  # Should infer as str but doesn't
"""

module = astroid.parse(code)

# Find the two result assignments
result1_assign = None
result2_assign = None

for node in module.body:
    if isinstance(node, nodes.Assign):
        if isinstance(node.targets[0], nodes.AssignName):
            if node.targets[0].name == "result1":
                result1_assign = node
            elif node.targets[0].name == "result2":
                result2_assign = node

# Infer the values of result1 and result2
if result1_assign and result2_assign:
    print("Inferring result1:")
    for inferred in result1_assign.value.infer():
        print(f"  - {inferred} (type: {type(inferred).__name__})")
        if hasattr(inferred, 'value'):
            print(f"    value: {inferred.value}, type: {type(inferred.value).__name__}")

    print("\nInferring result2:")
    for inferred in result2_assign.value.infer():
        print(f"  - {inferred} (type: {type(inferred).__name__})")
        if hasattr(inferred, 'value'):
            print(f"    value: {inferred.value}, type: {type(inferred.value).__name__}")

def register(manager: AstroidManager) -> None:
    manager.register_transform(
        Call,
        inference_tip(infer_typing_typevar_or_newtype),
        looks_like_typing_typevar_or_newtype,
    )
    manager.register_transform(
        Subscript, inference_tip(infer_typing_attr), _looks_like_typing_subscript
    )

    manager.register_transform(
        FunctionDef, inference_tip(infer_typedDict), _looks_like_typedDict
    )

    manager.register_transform(
        Call, inference_tip(infer_typing_alias), _looks_like_typing_alias
    )
    manager.register_transform(
        Call, inference_tip(infer_special_alias), _looks_like_special_alias
    )

    if PY312_PLUS:
        register_module_extender(manager, "typing", _typing_transform)
        manager.register_transform(
            ClassDef,
            inference_tip(infer_typing_generic_class_pep695),
            _looks_like_generic_class_pep695,
        )

