def _looks_like_typing_cast(node: Call) -> bool:
    """Check if the node corresponds to typing.cast call."""
    func = node.func
    if isinstance(func, Attribute):
        return func.attrname == "cast" and func.expr.as_string() == "typing"
    if isinstance(func, Name):
        return func.name == "cast"
    return False


def infer_typing_cast(
    node: Call, context: InferenceContext | None = None
) -> Iterator[InferenceResult]:
    """Infer typing.cast call.

    typing.cast(typ, val) returns val at runtime, and typ is only used by type checkers.
    """
    if len(node.args) != 2:
        # typing.cast requires exactly 2 arguments
        raise UseInferenceDefault

    # We only care about the second argument (the value)
    val_arg = node.args[1]

    # Create a new context for each inference to avoid caching issues
    new_context = context.clone() if context else InferenceContext()

    # Infer the value argument
    try:
        for inferred in val_arg.infer(context=new_context):
            yield inferred
    except InferenceError:
        raise UseInferenceDefault


def register(manager: AstroidManager) -> None:
    manager.register_transform(
        Call,
        inference_tip(infer_typing_typevar_or_newtype),
        looks_like_typing_typevar_or_newtype,
    )
    manager.register_transform(
        Subscript, inference_tip(infer_typing_attr), _looks_like_typing_subscript
    )

    manager.register_transform(
        FunctionDef, inference_tip(infer_typedDict), _looks_like_typedDict
    )

    manager.register_transform(
        Call, inference_tip(infer_typing_alias), _looks_like_typing_alias
    )
    manager.register_transform(
        Call, inference_tip(infer_special_alias), _looks_like_special_alias
    )

    # Register transform for typing.cast
    manager.register_transform(
        Call, inference_tip(infer_typing_cast), _looks_like_typing_cast
    )

    if PY312_PLUS:
        register_module_extender(manager, "typing", _typing_transform)
        manager.register_transform(
            ClassDef,
            inference_tip(infer_typing_generic_class_pep695),
            _looks_like_generic_class_pep695,
        )

